const escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const catalog=[['writing','毕业论文','论文与报告'],['proposal','开题报告','论文与报告'],['summary','文献综述','论文与报告'],['taskbook','任务书','论文与报告'],['article','期刊文章','论文与报告'],['course','课程作业','论文与报告'],['practice','实践报告','论文与报告'],['idea','课题思路','研究准备'],['questionnaire','问卷设计','研究准备'],['analysis','数据分析','研究准备'],['quick','快速写作','研究准备']];
export function catalogNav(id){return `<nav class="writing-catalog" aria-label="写作任务">${['论文与报告','研究准备'].map(group=>`<div><strong>${group}</strong><div>${catalog.filter(t=>t[2]===group).map(([key,label])=>`<a href="#tool/${key}" ${key===id?'aria-current="page"':''}>${label}</a>`).join('')}</div></div>`).join('')}</nav>`;}
const common=[['填写研究信息','填写题目、学段和研究要求；目标字数是规划值，不会自动补齐内容。'],['核对文献与材料','导入有权使用的材料，核对解析正文。当前不自动检索文献，也不会将材料用于 AI 生成。'],['确认结构','生成本地模板，调整章节和顺序；示例不是生成结果。'],['编辑并保存','根据真实研究填写正文，保存草稿；切换任务前保存或导出。'],['导出与核对','导出当前已填写内容，再核对事实、引用及学校格式。']];
const specific={questionnaire:[['填写研究目标','说明主题、目标人群及维度。'],['编辑问卷草稿','填写问题、选项与答题说明；先进行小范围试填。'],['导出问卷','当前提供本地草稿，在线发布、二维码与答卷回收尚未接入。']],analysis:[['填写分析计划','记录研究问题、变量、数据来源和预期方法。'],['准备真实数据','说明缺失值、样本与变量类型；不能把计划当成计算结果。'],['保存分析计划','当前保存与导出计划，不执行统计检验或输出分析数值。']],practice:[['记录真实经历','填写单位、岗位、时间及实际工作内容。'],['整理报告','在框架中补充过程、发现与反思，不编造实践经历。'],['保存与导出','保存草稿，逐项核对单位、日期和成果。']],idea:[['明确研究问题','输入专业、兴趣、研究问题和可获得的数据。'],['讨论研究可行性','核对研究范围、方法与资料来源。'],['保存计划','当前生成整理框架，不替代真实文献检索。']]};
export function guideMarkup(id){const name=catalog.find(t=>t[0]===id)?.[1]||'写作任务';return `<button class="btn secondary guide-toggle" type="button" aria-expanded="true" aria-controls="writing-guide">隐藏操作指南</button><section id="writing-guide" class="writing-guide" aria-label="${escape(name)}操作指南"><div><h2>${escape(name)} · 操作指南</h2><p>按当前任务准备材料，操作过程中可随时隐藏。</p></div><ol>${(specific[id]||common).map(([title,desc],i)=>`<li><span>${i+1}</span><div><b>${title}</b><p>${desc}</p></div></li>`).join('')}</ol><p class="guide-boundary">本地数据保存在当前浏览器，请及时导出。模型、在线检索、发布与收费状态以页面说明为准。</p></section>`;}
export function bindGuide(){const button=document.querySelector('.guide-toggle'),panel=document.querySelector('#writing-guide');if(!button||!panel)return;let open=true;try{open=localStorage.getItem('paperknow-writing-guide')!=='hidden';}catch{}const apply=()=>{panel.hidden=!open;button.setAttribute('aria-expanded',String(open));button.textContent=open?'隐藏操作指南':'操作指南';};apply();button.onclick=()=>{open=!open;apply();try{localStorage.setItem('paperknow-writing-guide',open?'visible':'hidden');}catch{}};}

export const writingHeading=()=>`<div class="creation-heading"><div><h1>AI 写作</h1><p>从选题与材料出发，按步骤形成可编辑的研究成果。</p></div><a class="btn secondary" href="#assets">写作记录</a></div>`;
export const capabilityMarkup=()=>`<section class="writing-capabilities" aria-label="AI 写作能力"><header><div><span class="overline">PAPERKNOW AI WRITING</span><h2>完整写作能力</h2><p>先准备研究信息，再按需调用生成、编辑、研究辅助和交付能力。</p></div><span class="capability-summary"><b>14</b> 项能力入口</span></header><div class="capability-groups"><div><h3>智能生成</h3><div class="capability-list"><button type="button" data-writing-capability="title">智能拟题 <small>根据研究方向给出候选题目</small><em>待接入</em></button><button type="button" data-writing-capability="abstract">摘要与研究问题 <small>提炼背景、目标和贡献</small><em>待接入</em></button><button type="button" data-writing-capability="outline">AI 生成大纲 <small>结合材料规划章节结构</small><em>当前可编辑模板</em></button><button type="button" data-writing-capability="chapter">分章节写作 <small>按章节生成并保留上下文</small><em>待接入</em></button></div></div><div><h3>深度编辑</h3><div class="capability-list"><button type="button" data-writing-capability="polish">学术润色 <small>改善表达并保留原意</small><em>待接入</em></button><button type="button" data-writing-capability="rewrite">改写与降重 <small>调整句式，保留事实与引用</small><em>待接入</em></button><button type="button" data-writing-capability="expand">扩写与缩写 <small>控制篇幅和信息密度</small><em>待接入</em></button><button type="button" data-writing-capability="translate">多语言改写 <small>处理中英研究文本转换</small><em>待接入</em></button></div></div><div><h3>研究辅助</h3><div class="capability-list"><button type="button" data-writing-capability="literature">文献检索与推荐 <small>查找来源并记录 DOI、作者和年份</small><em>待接入</em></button><button type="button" data-writing-capability="citation">引用与参考文献 <small>插入引用并按格式生成列表</small><em>待接入</em></button><button type="button" data-writing-capability="visual">图表、公式与代码 <small>在正文中生成可编辑研究内容</small><em>待接入</em></button><button type="button" data-writing-capability="template">学校与期刊模板 <small>套用格式要求并检查结构</small><em>待接入</em></button></div></div><div><h3>质量与交付</h3><div class="capability-list"><button type="button" data-writing-capability="check">查重与 AIGC 检测 <small>查看报告并定位需要修改的段落</small><em>已有独立入口</em></button><button type="button" data-writing-capability="export">DOCX、PDF 与投稿包 <small>导出正文、引用和附件</small><em>已有导出</em></button></div></div></div><p class="capability-status" id="writing-capability-status" role="status">能力入口已覆盖；标记“待接入”的项目会按流程逐项连接模型服务。</p></section>`;
export function bindCapabilities(){document.querySelectorAll('[data-writing-capability]').forEach(button=>button.addEventListener('click',()=>{const label=button.textContent.split(' ')[0]||'该能力';const state=button.querySelector('em')?.textContent||'';const status=document.querySelector('#writing-capability-status');if(status)status.textContent=state.includes('已有')?`${label}已可使用，可从对应入口继续。`:`${label}入口已准备，当前等待模型服务接入。`;document.querySelectorAll('[data-writing-capability]').forEach(item=>item.classList.remove('selected'));button.classList.add('selected');}));}
export function retainWritingCatalog(previous,current,focused=previous?.contains(document.activeElement)?document.activeElement:null){if(!previous||!current)return;const selected=current.querySelector('[aria-current="page"]')?.getAttribute('href');for(const link of previous.querySelectorAll('a')){if(link.getAttribute('href')===selected)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');}current.replaceWith(previous);focused?.focus({preventScroll:true});}
